 "content": "def transform(grid):
    """Extend the colored rectangle along rows/columns marked by singleton dots."""
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    # Find the main solid rectangle (largest component of color 2).
    cells = [(r, c) for r in range(h) for c in range(w) if a[r][c] == 2]
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    # Color 2 extension follows marker rays: any row containing a 1 is filled
    # across the full width; any column containing a 1 is filled through the
    # rectangle's height and onward to the boundary, as demonstrated.
    marked_rows = {r for r in range(h) if 1 in a[r]}
    marked_cols = {c for c in range(w) if any(a[r][c] == 1 for r in range(h))}
    # Marked rows extend the rectangle's horizontal band completely across.
    for r in marked_rows:
        for c in range(w):
            if a[r][c] == 0:
                a[r][c] = 2
    # Marked columns extend the vertical stripe through the whole grid, but
    # retain existing nonzero markers.
    for c in marked_cols:
        for r in range(h):
            if a[r][c] == 0:
                a[r][c] = 2
    return a

