    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    # Each singleton marker is on one side of the rectangle. It projects a
    # continuation of the rectangle's color along the perpendicular axis.
    # The continuation ends at the marker (which itself remains unchanged).
    markers = [(r, c) for r in range(h) for c in range(w) if a[r][c] not in (0, 2)]
    for r, c in markers:
        if r < r0:
            for rr in range(r, r0):
                if a[rr][c] == 0:
                    a[rr][c] = 2
        elif r > r1:
            for rr in range(r1 + 1, r + 1):
