 "content": "def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    cells = [(r, c) for r in range(h) for c in range(w) if a[r][c] == 2]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    markers = [(r, c) for r in range(h) for c in range(w) if a[r][c] == 1]

    # Extend each horizontal strip of the rectangle to the grid edges,
    # stopping on a side where a singleton marker blocks the extension.
    for r in range(r0, r1 + 1):
        blocked_left = any(rr == r and cc < c0 for rr, cc in markers)
        blocked_right = any(rr == r and cc > c1 for rr, cc in markers)
        if not blocked_left:
            for c in range(c0):
                if a[r][c] == 0:
                    a[r][c] = 2
        if not blocked_right:
            for c in range(c1 + 1, w):
                if a[r][c] == 0:
                    a[r][c] = 2

    # Extend each vertical strip similarly; markers above/below block that
    # column's extension on their side.
    for c in range(c0, c1 + 1):
        blocked_top = any(cc == c and rr < r0 for rr, cc in markers)
        blocked_bottom = any(cc == c and rr > r1 for rr, cc in markers)
        if not blocked_top:
            for r in range(r0):
                if a[r][c] == 0:
                    a[r][c] = 2
        if not blocked_bottom:
            for r in range(r1 + 1, h):
                if a[r][c] == 0:
                    a[r][c] = 2
    return a
